steps.command:
python3 - <<'EOF'
p='billing/refunds.py'
s=open(p).read()
a=s.index("def refund_invoice")
b=s.index("def credit_invoice")
new='''def _refundable_payments(ctx: Context, invoice_id: InvoiceId) -> list[Payment]:
    payments = [
        payment
        for payment in successful_payments(ctx, invoice_id)
        if payment["gateway_ref"] is not None and payment["amount"] > payment["refunded_amount"]
    ]
    return sorted(payments, key=lambda payment: (payment["created_at"], payment["id"]))


def _credit_returned(ctx: Context, invoice: Invoice) -> bool:
    return any(
        entry["reason"] == "refund" and entry["invoice_id"] == invoice["id"]
        for entry in ctx.store.ledger_for(invoice["customer_id"])
    )


def refund_invoice(
    ctx: Context, invoice_id: InvoiceId, reason: str = "requested_by_customer", amount: Cents | None = None
) -> CreditNote:
    """Refund money paid on an invoice back to the original payment method.

    With ``amount`` refunds that much (oldest payments first); without it refunds everything that
    remains refundable and returns any applied account credit.
    """
    invoice = ctx.store.require_invoice(invoice_id)
    if invoice["status"] != "paid":
        raise InvalidStateError("only paid invoices can be refunded")
    payments = _refundable_payments(ctx, invoice_id)
    refundable = Cents(sum(payment["amount"] - payment["refunded_amount"] for payment in payments))
    return_credit = amount is None and invoice["credit_applied"] > 0 and not _credit_returned(ctx, invoice)
    if amount is None:
        if refundable == 0 and not return_credit:
            raise InvalidStateError("invoice has nothing left to refund")
        to_refund = refundable
    else:
        if amount <= 0:
            raise ValidationError("refund amount must be positive")
        if amount > refundable:
            raise ValidationError(f"cannot refund more than {refundable} on this invoice")
        to_refund = amount
    refunded = Cents(0)
    for payment in payments:
        take = Cents(min(to_refund - refunded, payment["amount"] - payment["refunded_amount"]))
        if take <= 0:
            break
        result = ctx.gateway.refund(cast(str, payment["gateway_ref"]), take)
        if not result["ok"]:
            raise InvalidStateError(f"gateway refused refund for payment {payment['id']}")
        payment["refunded_amount"] = Cents(payment["refunded_amount"] + take)
        payment["status"] = "refunded" if payment["refunded_amount"] >= payment["amount"] else "partially_refunded"
        refunded = Cents(refunded + take)
        emit(ctx, "payment.refunded", {"payment": payment_json(payment)})
    total = refunded
    if return_credit:
        add_entry(ctx, invoice["customer_id"], invoice["credit_applied"], "refund", invoice["id"])
        total = Cents(total + invoice["credit_applied"])
    return _credit_note(ctx, invoice_id, total, reason, True)


'''
s=s[:a]+new+s[b:]
s=s.replace("from .context","from typing import cast\n\nfrom .context",1).replace("import Cents, CreditNote, InvoiceId","import Cents, CreditNote, Invoice, InvoiceId, Payment")
open(p,'w').write(s)

p='billing/engine.py'
s=open(p).read()
s=s.replace('''    def refund(self, invoice_id: InvoiceId, reason: str = "requested_by_customer") -> CreditNote:
        return refunds.refund_invoice(self.ctx, invoice_id, reason)''','''    def refund(
        self, invoice_id: InvoiceId, reason: str = "requested_by_customer", amount: Cents | None = None
    ) -> CreditNote:
        return refunds.refund_invoice(self.ctx, invoice_id, reason, amount)''')
open(p,'w').write(s)

p='billing/api.py'
s=open(p).read()
s=s.replace('''    note = engine.refund(InvoiceId(params[0]), _optional_str(body, "reason") or "requested_by_customer")''','''    amount = Cents(_int(body, "amount")) if body.get("amount") is not None else None
    note = engine.refund(InvoiceId(params[0]), _optional_str(body, "reason") or "requested_by_customer", amount)''')
open(p,'w').write(s)
EOF
grep -n "Cents" billing/engine.py billing/api.py | head -4; sed -n 1,14p billing/api.py
